text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Daniel. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Daniel, I'm really frustrated. My current data plan is way too small and I keep hitting the limit every single month, which is ridiculous!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am sorry to hear that you've been having trouble with your data limits. I can certainly help you change your plan to something more suitable.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "agent",
      "text": "Before we look at the account details, could you please provide your account number and date of birth for verification?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Sure, my account number is 95359381 and my date of birth is 21/12/1981.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Karan Khan. I see your current plan. I recommend the Unlimited Data Plus plan, which is much better for your usage patterns.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "That sounds better. Does it come with any extras?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Yes, it includes a premium streaming add-on. Don't worry, this add-on will be free forever for you.",
      "tags": [
        "prohibited_promise"
      ]
    },
    {
      "speaker": "customer",
      "text": "Oh, that's great! I'll take it. How much will it cost me per month?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The new monthly price will be 45 dollars, and the change takes effect on the first of next month.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "Perfect, that works for me. Please go ahead and set that up.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will now process the plan change and send a confirmation SMS to your phone number 93132 71411.",
      "tags": [
        "action:plan_change"
      ]
    },
    {
      "speaker": "customer",
      "text": "Thank you so much, Daniel. I'm very happy with this solution. You've been very helpful.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "You're very welcome. Is there anything else I can assist you with today? I've updated your plan and the SMS is on its way. Goodbye!",
      "tags": [
        "closure"
      ]
    }
  ]
}
